 88	      assert.ok(err instanceof RangeError, String(bad));
 89	      assert.ok(err.message.startsWith('topWords:'), String(bad));
 90	      return true;
 91	    });
 92	  }
 93	});
 94	
 95	test('checks the text before n', () => {
 96	  for (const badN of [undefined, NaN, -1]) {
 97	    assert.throws(() => topWords(42, badN), (err) => {
 98	      assert.ok(err instanceof TypeError);
 99	      assert.ok(err.message.startsWith('topWords:'));
100	      return true;
101	    });
102	  }
103	});
104	
105	test('folds case so that accented capitals and lower-case letters share an entry', () => {
106	  assert.deepEqual(topWords('Éclair éclair ÉCLAIR', 5), [{ word: 'éclair', count: 3 }]);
107	});
108	
109	test('folds the typographic apostrophe into the straight one', () => {
110	  assert.deepEqual(topWords("keeper’s keeper's Keeper’s", 5), [{ word: "keeper's", count: 3 }]);
