127	    { word: 'zebra', count: 1 },
128	    { word: 'éclair', count: 1 },
129	  ]);
130	});
131	
132	test('keeps hyphenated compounds and contractions whole and counts numbers as words', () => {
133	  assert.deepEqual(topWords("well-known don't 42 well-known 42 well-known", 5), [
134	    { word: 'well-known', count: 3 },
