140	test('returns fresh objects on every call', () => {
141	  const first = topWords('apple apple banana', 2);
142	  first[0].count = 99;
143	  first[0].word = 'changed';
144	  first.pop();
145	  assert.deepEqual(topWords('apple apple banana', 2), [
146	    { word: 'apple', count: 2 },
147	    { word: 'banana', count: 1 },
148	  ]);
149	});
