 16	  ["x x x", 2, 2],
 17	];
 18	
 19	const assertThrowsWithPrefix = (fn, ErrorClass) => {
 20	  assert.throws(fn, (err) => {
 21	    assert.ok(err instanceof ErrorClass);
 22	    assert.ok(err.message.startsWith('readingTimeMinutes:'));
 23	    return true;
 24	  });
 25	};
 26	
 27	test('returns 0 for the empty string', () => {
 28	  assert.equal(readingTimeMinutes(''), 0);
 29	});
 30	
 31	test('returns 0 for whitespace and punctuation only', () => {
 32	  assert.equal(readingTimeMinutes(' \n -- ... '), 0);
 33	});
 34	
 35	test('rounds a single word up to one minute', () => {
 36	  assert.equal(readingTimeMinutes('hello'), 1);
 37	});
 38	
 39	test('returns 1 for exactly 200 words at the default rate', () => {
 40	  assert.equal(readingTimeMinutes(words(200)), 1);
 41	});
 42	
 43	test('returns 2 for 201 words at the default rate', () => {
 44	  assert.equal(readingTimeMinutes(words(201)), 2);
 45	});
 46	
 47	test('returns 2 for exactly 400 words at the default rate', () => {
 48	  assert.equal(readingTimeMinutes(words(400)), 2);
 49	});
 50	
 51	test('throws a TypeError naming the function for a non-string', () => {
 52	  for (const bad of [undefined, null, 12, {}, ['a b']]) {
 53	    assertThrowsWithPrefix(() => readingTimeMinutes(bad), TypeError);
 54	  }
 55	});
 56	
 57	test('matches every row of the reference table', () => {
 58	  for (const [text, wpm, expected] of CASES) {
 59	    const actual = wpm === null ? readingTimeMinutes(text) : readingTimeMinutes(text, wpm);
 60	    assert.equal(actual, expected, JSON.stringify([text, wpm]));
 61	  }
 62	});
 63	
 64	test('returns 2 for a 270-word text spread over three paragraphs', () => {
 65	  const sentence = 'The quiet river runs past the old stone mill.';
 66	  const paragraph = Array.from({ length: 10 }, () => sentence).join(' ');
 67	  const text = [paragraph, paragraph, paragraph].join('\n\n');
 68	  assert.equal(wordCount(text), 270);
 69	  assert.equal(readingTimeMinutes(text), 2);
 70	});
 71	
 72	test('throws a RangeError for a zero, negative, NaN or infinite wpm', () => {
 73	  for (const bad of [0, -1, -200, NaN, Infinity, -Infinity]) {
 74	    assertThrowsWithPrefix(() => readingTimeMinutes('hello', bad), RangeError);
 75	  }
 76	});
 77	
 78	test('throws a RangeError for a numeric string or null wpm', () => {
 79	  for (const bad of ['200', null]) {
 80	    assertThrowsWithPrefix(() => readingTimeMinutes('hello', bad), RangeError);
 81	  }
 82	});
 83	
 84	test('accepts a fractional wpm and rounds the result up', () => {
 85	  // 301 / 150.5 is exactly 2, while truncating the rate to 150 would give 3.
 86	  assert.equal(readingTimeMinutes(words(301), 150.5), 2);
 87	  // 302 / 150.5 is just over 2, so it rounds up to 3.
 88	  assert.equal(readingTimeMinutes(words(302), 150.5), 3);
 89	});
 90	
 91	test('uses the default rate of 200 when wpm is explicitly undefined', () => {
 92	  assert.equal(readingTimeMinutes(words(201), undefined), 2);
 93	  assert.equal(readingTimeMinutes(words(200), undefined), 1);
 94	});
 95	
 96	test('validates the text before the rate', () => {
 97	  assertThrowsWithPrefix(() => readingTimeMinutes(42, 0), TypeError);
 98	  assertThrowsWithPrefix(() => readingTimeMinutes(undefined, NaN), TypeError);
 99	});
100	
101	test('counts hyphenated compounds, contractions and decimals like wordCount', () => {
102	  const text = "A well-known fact: it doesn't cost 3.14 dollars.";
103	  assert.equal(readingTimeMinutes(text, 1), wordCount(text));
104	});
